def makefile_words(raw):
    words = []
    current = bytearray()
    escaped = False
    for byte in raw:
        if escaped:
            if byte == 10:
                escaped = False
                continue
            current.append(byte)
            escaped = False
        elif byte == 92:
            escaped = True
        elif byte in (9, 10, 13, 32):
            if current:
                words.append(bytes(current))
                current.clear()
        else:
            current.append(byte)
    if escaped:
        raise ValueError("Cargo dep-info ends with an incomplete escape")
    if current:
        words.append(bytes(current))
    return words
