    write_private_file(os.path.join(private_root, "go.mod"), b"")
    private_tool = os.path.join(private_root, "bin", "gofumpt")
    write_private_file(private_tool, formatter_record["snapshot"]["content"], 0o500)
    if formatter_sidecar is not None:
