        "TERM": "dumb",
        "NO_COLOR": "1",
        "CLICOLOR": "0",
        "FORCE_COLOR": "0",
        "GODEBUG": "",
        "GOENV": "off",
        "GOMAXPROCS": "1",
        "GOTELEMETRY": "off",
        "GOTOOLCHAIN": "local",
        "GOWORK": "off",
        "GOPROXY": "off",
        "GOSUMDB": "off",
        "GOVCS": "*:off",
    }
