    canary_path = os.path.join(private_root, "inputs", "canary.go")
    write_private_file(canary_path, CANARY_INPUT)
    status, output, errors = run_child([private_tool, "-lang=go1.26", "-modpath=velvet.invalid/canary", "-l", canary_path], environment)
    if status != 0 or output != os.fsencode(canary_path) + b"\n" or errors:
        raise EvidenceError("gofumpt listing canary returned unexpected evidence")
    status, output, errors = run_child([private_tool, "-lang=go1.26", "-modpath=velvet.invalid/canary"], environment, CANARY_INPUT)
    if status != 0 or output != CANARY_OUTPUT or errors:
        raise EvidenceError("gofumpt formatting canary returned unexpected evidence")
    assert_all_originals()

    module_semantics = {None: ("go1", "")}
    for index, (manifest, record) in enumerate(sorted(controls.items())):
        private_mod = os.path.join(private_root, "controls", f"{index:04}.mod")
        write_private_file(private_mod, record["snapshot"]["content"])
        status, output, errors = run_go(
