SOURCE_LIMIT = 64 * 1024 * 1024
SOURCE_COUNT_LIMIT = 4096
CONTROL_LIMIT = 16 * 1024 * 1024
CONTROL_COUNT_LIMIT = 256
PROGRAM_LIMIT = 128 * 1024 * 1024
CHILD_TIMEOUT = 30.0
CLEANUP_TIMEOUT = 2.0
EXPECTED_VERSION = b"v0.11.0 (go1.26.5)\n"
EXPECTED_GO_VERSION = b"go version go1.26.5 darwin/arm64\n"
CANARY_INPUT = b'package canary\n\nimport ("fmt"\n"os")\n\nconst mode = 022\n\nfunc f( ){fmt.Println(os.Args )}\n'
CANARY_OUTPUT = b'package canary\n\nimport (\n\t"fmt"\n\t"os"\n)\n\nconst mode = 0o22\n\nfunc f() { fmt.Println(os.Args) }\n'
PRIVATE_PREFIX = "velvet-glove-gofumpt-"
handled_signals = (signal.SIGHUP, signal.SIGINT, signal.SIGTERM)


def safe_text(value, label):
    if not isinstance(value, str) or not value:
        raise ValueError(f"{label} is empty or not text")
    for character in value:
        codepoint = ord(character)
        if codepoint < 32 or codepoint == 127 or 0xD800 <= codepoint <= 0xDFFF:
            raise ValueError(f"{label} contains a control or surrogate character")
    return value


class AdapterSignal(BaseException):
    def __init__(self, signum):
        super().__init__(f"received signal {signum}")
        self.signum = signum


class EvidenceError(Exception):
    pass


def fail(message):
    print(f"velvet-glove-gofumpt: {message}", file=sys.stderr)
    raise SystemExit(2)


